const COVERAGE_STATUS_META={ready:{label:'Sva objavljena pravila pokrivena',icon:'✓'},published:{label:'Profil postoji, predaja nije dovršena',icon:'i'},partial:{label:'Djelomičan profil',icon:'△'},missing:{label:'Nedostaje poseban profil',icon:'!'},external:{label:'Partnerska / združena pravila',icon:'↗'}};
function coverageEvaluation(record){
 if(record.scope!=='internal')return{status:'external',profiles:[],gaps:[record.note||'Pravila završetka određuje partnerska ustanova ili konzorcij.']};
 const found=(record.expectedProfileIds||[]).map(id=>VERIFIED_PROFILE_REGISTRY.find(p=>p.id===id)).filter(Boolean);
 const missing=(record.expectedProfileIds||[]).filter(id=>!VERIFIED_PROFILE_REGISTRY.some(p=>p.id===id));
 const mismatched=found.filter(p=>!p.programs?.includes(record.name)||!(record.expectedWorkTypes||[]).some(w=>p.workTypes?.includes(w)));
 if(missing.length||mismatched.length||!found.length){const gaps=[];if(missing.length)gaps.push(`Nedostaju profili: ${missing.join(', ')}`);if(mismatched.length)gaps.push(`Profil nije točno vezan uz program: ${mismatched.map(x=>x.id).join(', ')}`);if(!found.length&&!missing.length)gaps.push('Nema zasebnog normativnog profila.');return{status:'missing',profiles:found,gaps}}
 const partial=found.filter(p=>p.status!=='verified');
 if(partial.length)return{status:'partial',profiles:found,gaps:[`Djelomični profili: ${partial.map(x=>x.id).join(', ')}`]};
 const gaps=[];
 if(record.requiresSubmissionCoverage!==false&&found.some(p=>!(p.submissionFacts||[]).length))gaps.push('Nije ugrađen puni Submission Gate prije i nakon obrane.');
 if(found.some(p=>!(p.sources||[]).length))gaps.push('Nedostaje službeni izvor profila.');
 if(!found.some(p=>p.fieldValidation))gaps.push('Nema strukturirane terenske validacije na stvarnom dokumentu.');
 return{status:gaps.some(x=>x.includes('Submission Gate')||x.includes('službeni izvor'))?'published':'ready',profiles:found,gaps};
}
function coverageSnapshot(){const rows=INSTITUTIONAL_COVERAGE_MATRIX.programs.map(program=>({...program,evaluation:coverageEvaluation(program)}));const counts={total:rows.length,internal:rows.filter(x=>x.scope==='internal').length,external:rows.filter(x=>x.evaluation.status==='external').length};for(const id of Object.keys(COVERAGE_STATUS_META))counts[id]=rows.filter(x=>x.evaluation.status===id).length;counts.profiled=rows.filter(x=>['ready','published','partial'].includes(x.evaluation.status)).length;counts.completion=Math.round(((counts.ready+counts.published*.65+counts.partial*.3)/Math.max(1,counts.internal))*100);return{rows,counts}}
