function fpzgScheduleType(){const id=currentDefinitionId();if(['fpzg-politologija-zavrsni','fpzg-novinarstvo-zavrsni-tekst','fpzg-novinarstvo-zavrsni-av'].includes(id))return'final';if(['fpzg-politologija-diplomski','fpzg-nacionalna-sigurnost-diplomski','fpzg-novinarstvo-diplomski'].includes(id))return'graduate';return null}
function hrDate(value,withTime=false){if(!value)return'—';const d=new Date(value.length===10?value+'T12:00:00':value);return new Intl.DateTimeFormat('hr-HR',{day:'2-digit',month:'2-digit',year:'numeric',...(withTime?{hour:'2-digit',minute:'2-digit'}:{})}).format(d)}
function dateRange(a,b){return`${hrDate(a)} do ${hrDate(b)}`}
function deadlineState(entry){const now=Date.now(),start=new Date((entry.defenseStart||entry.start)+'T00:00:00').getTime(),end=new Date((entry.defenseEnd||entry.end)+'T23:59:59').getTime(),cutoff=entry.cutoff?new Date(entry.cutoff).getTime():null;if(now>end)return{key:'closed',label:'rok završen'};if(now>=start&&now<=end)return{key:'active',label:'obrane u tijeku'};if(cutoff&&now>cutoff)return{key:'cutoff',label:'rok prijave prošao'};return{key:'upcoming',label:'nadolazeći rok'}}
function fpzgDeadlineEntries(type=fpzgScheduleType(),cohort=currentFpzgCohort()){if(type==='final')return FPZG_SUBMISSION_CALENDAR.final.windows.filter(x=>x.cohorts.includes(cohort));if(type==='graduate')return FPZG_SUBMISSION_CALENDAR.graduate.sessions;return[]}
function populateFpzgDeadlineOptions(){const type=fpzgScheduleType(),show=!!type&&currentSubmissionPhase()!=='document',cohortField=$('#fpzgCohortField'),deadlineField=$('#fpzgDeadlineField'),select=$('#fpzgDeadline');cohortField?.classList.toggle('hidden',!(show&&type==='final'));deadlineField?.classList.toggle('hidden',!show);if(!show||!select)return;const previous=select.value,entries=fpzgDeadlineEntries(type);select.innerHTML=entries.map(x=>`<option value="${escapeHtml(x.id)}">${escapeHtml(x.label)} · ${escapeHtml(dateRange(x.defenseStart||x.start,x.defenseEnd||x.end))}</option>`).join('');if(entries.some(x=>x.id===previous))select.value=previous;else{const next=entries.find(x=>new Date((x.defenseEnd||x.end)+'T23:59:59').getTime()>=Date.now())||entries.at(-1);if(next)select.value=next.id}const help=$('#fpzgDeadlineHelp');if(help)help.textContent=type==='final'?'Datum obrane mora biti radni dan unutar odabranog razdoblja, a prijava najmanje tri radna dana ranije.':'Odabrani rok određuje krajnji datum D2 obrasca, uvezanog rada i dokumentacije te razdoblje obrane.'}
function updateSubmissionContextFields(){populateFpzgDeadlineOptions()}
function auxState(el,state,label){if(!el)return;el.className=`file-state ${state||''}`;el.textContent=label}
