function renderActionPlan(r){const errors=(r.issues||[]).filter(x=>x.severity==='error'),warnings=(r.issues||[]).filter(x=>x.severity==='warning'),infos=(r.issues||[]).filter(x=>x.severity==='info'),quick=warnings.filter(x=>['formatting','elements'].includes(x.category)),structural=warnings.filter(x=>!quick.includes(x)),manual=(r.details?.manualChecks||[]).map(x=>({title:'Ručna provjera',detail:x,where:'Službene upute'}));const items=(arr,limit=6)=>arr.slice(0,limit).map(x=>{const _tool=suggestTool(x);return `<div class="action-item"><strong>${escapeHtml(x.title)}</strong><p>${escapeHtml(x.detail)}</p><small>${escapeHtml(x.where||x.category||'')}</small>${_tool?`<a class="action-tool" href="${escapeHtml(_tool.href)}"><i data-lucide="wrench"></i> ${escapeHtml(_tool.label)} →</a>`:''}</div>`}).join('')||'<div class="action-empty"><i data-lucide="check-circle"></i> Nema stavki u ovoj skupini.</div>';$('#actionPlan').innerHTML=`<div class="action-overview"><div class="action-stat"><span>PRVO ISPRAVI</span><b>${errors.length}</b></div><div class="action-stat"><span>BRZE DORADE</span><b>${quick.length}</b></div><div class="action-stat"><span>RUČNO POTVRDI</span><b>${manual.length+infos.length}</b></div></div><div class="action-columns"><section class="action-column"><h3>1. Kritični problemi</h3><p>Stavke koje najviše utječu na tehničku usklađenost.</p>${items(errors)}</section><section class="action-column"><h3>2. Brze i strukturne dorade</h3><p>Oblikovanje, elementi i upozorenja koja se obično brzo popravljaju.</p>${items([...quick,...structural])}</section><section class="action-column"><h3>3. Ručna završna provjera</h3><p>Stavke koje parser ne može pouzdano odlučiti bez konteksta.</p>${items([...manual,...infos])}</section></div>`}
function downloadBlob(content,type,name){const blob=new Blob([content],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function buildStandaloneReport(r){const status=PROFILE_STATUS[r.profileStatus]||PROFILE_STATUS.generic,authority=PROFILE_AUTHORITY[r.details?.ruleAuthority]||PROFILE_AUTHORITY.generic,sub=r.submission,subHtml=sub?`<h2>Spremnost za predaju</h2><section class="hero"><h3>${escapeHtml(statusLabel(sub.overall))}</h3><div class="grid"><div class="box"><span>Dokument</span><b>${escapeHtml(statusLabel(sub.document.status))}</b></div><div class="box"><span>Datoteke</span><b>${escapeHtml(statusLabel(sub.files.status))}</b></div><div class="box"><span>Postupak</span><b>${escapeHtml(statusLabel(sub.procedure.status))}</b></div><div class="box"><span>Faza</span><b>${escapeHtml(sub.blueprint.phase)}</b></div></div>${sub.blueprint.selectedDeadline?`<p><strong>Odabrani godišnji rok:</strong> ${escapeHtml(sub.blueprint.selectedDeadline.label)} · ${escapeHtml(dateRange(sub.blueprint.selectedDeadline.defenseStart||sub.blueprint.selectedDeadline.start,sub.blueprint.selectedDeadline.defenseEnd||sub.blueprint.selectedDeadline.end))}</p>`:''}${sub.files.blockers?.length?`<p><strong>Blokira:</strong> ${escapeHtml(sub.files.blockers.join(' · '))}</p>`:''}${sub.procedure.incomplete?.length?`<p><strong>Nepotvrđeno:</strong> ${escapeHtml(sub.procedure.incomplete.map(x=>x.label).join(' · '))}</p>`:''}</section>`:'';const checkRows=(r.checks||[]).map(c=>`<tr><td>${escapeHtml(c.title)}</td><td>${c.max===0?'Informativno':c.status==='pass'?'U redu':c.status==='fail'?'Važno':'Provjeri'}</td><td>${escapeHtml(c.detail)}</td><td>${c.max===0?'—':`${Math.round(c.earned*10)/10}/${c.max}`}</td></tr>`).join('');const issueRows=(r.issues||[]).map(i=>`<article class="issue ${i.severity}"><h3>${escapeHtml(i.title)}</h3><p>${escapeHtml(i.detail)}</p><small>${escapeHtml(i.where||i.category)}</small></article>`).join('')||'<p>Nema prijavljenih problema.</p>';const sourceRows=(r.details?.sources||[]).map(x=>`<li><a href="${escapeHtml(x.url)}">${escapeHtml(x.title)}</a></li>`).join('');return`<!doctype html><html lang="hr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Lekta izvještaj — ${escapeHtml(r.file.name)}</title><style>body{font:15px/1.55 Arial,sans-serif;color:#172033;max-width:1050px;margin:40px auto;padding:0 24px}h1{font-size:30px;margin-bottom:4px}.muted{color:#667085}.hero{border:1px solid #dfe4ee;border-radius:18px;padding:22px;margin:22px 0}.score{font-size:42px;font-weight:800}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.box{border:1px solid #dfe4ee;border-radius:12px;padding:12px}.box span{display:block;color:#667085;font-size:11px}.box b{font-size:19px}table{width:100%;border-collapse:collapse;margin:16px 0}th,td{text-align:left;border-bottom:1px solid #dfe4ee;padding:9px;vertical-align:top}th{font-size:11px;color:#667085}.issue{border-left:4px solid #d08b00;padding:10px 13px;margin:9px 0;background:#fafafa}.issue.error{border-color:#c9364f}.issue.info{border-color:#246fb8}.issue h3{font-size:14px;margin:0}.issue p{margin:4px 0}.issue small{color:#667085}.note{padding:12px;background:#eef2ff;border-radius:10px}@media(max-width:700px){.grid{grid-template-columns:1fr 1fr}}</style></head><body><h1>Lekta izvještaj</h1><p class="muted">Generirano ${escapeHtml(new Date(r.generatedAt).toLocaleString('hr-HR'))} · verzija ${escapeHtml(r.appVersion||APP_VERSION)}</p><section class="hero"><div class="score">${r.score??'—'}/100</div><h2>${escapeHtml(r.file.name)}</h2><p>${escapeHtml(r.profile)}</p>${r.details?.sources?.length?`<p class="muted"><strong>Provjereno prema:</strong> <a href="${escapeHtml(r.details.sources[0].url)}">${escapeHtml(r.details.sources[0].title)}</a>${(r.details.documentDate||r.details.verifiedAt)?' ('+escapeHtml(r.details.documentDate||r.details.verifiedAt)+')':''}</p>`:''}<p class="muted">${escapeHtml(status.label)} · ${escapeHtml(authority.label)} · ${escapeHtml(r.details?.profileFingerprint||'bez otiska')}</p><div class="grid"><div class="box"><span>Problemi</span><b>${r.issues?.length||0}</b></div><div class="box"><span>Riječi</span><b>${fmt(r.stats?.officialWords||r.stats?.words)}</b></div><div class="box"><span>Izvori</span><b>${fmt(r.stats?.references)}</b></div><div class="box"><span>Citatnice</span><b>${fmt(r.stats?.citations)}</b></div></div></section><p class="note">Izvještaj ne sadrži tekst dokumenta. Rezultat je pomoćna tehnička provjera i ne zamjenjuje službene upute ni odluku mentora.</p>${subHtml}<h2>Automatske provjere</h2><table><thead><tr><th>Provjera</th><th>Status</th><th>Rezultat</th><th>Bodovi</th></tr></thead><tbody>${checkRows}</tbody></table><h2>Pronađeni problemi</h2>${issueRows}${sourceRows?`<h2>Izvori profila</h2><ul>${sourceRows}</ul>`:''}</body></html>`}
function downloadHtmlReport(){if(!currentResult)return;const exportResult=structuredClone(currentResult);exportResult.submission=submissionAssessment(currentResult);exportResult.details.pdfPreflight=currentPdfAudit;exportResult.details.metadataDocument=currentMetadataAudit;downloadBlob(buildStandaloneReport(exportResult),'text/html;charset=utf-8',`Lekta-izvjestaj-${currentResult.file.name.replace(/\.docx$/i,'')}.html`);trackEvent('report_downloaded',{source:'html',profileId:currentResult.details?.profileDefinitionId||''})}
function profileManifest(){const coverage=coverageSnapshot();return{appVersion:APP_VERSION,generatedAt:new Date().toISOString(),coverage:{verifiedAt:INSTITUTIONAL_COVERAGE_MATRIX.verifiedAt,summary:coverage.counts,programs:coverage.rows.map(x=>({id:x.id,unitId:x.unitId,name:x.name,level:x.level,scope:x.scope,expectedWorkTypes:x.expectedWorkTypes,status:x.evaluation.status,gaps:x.evaluation.gaps,profileIds:x.evaluation.profiles.map(p=>p.id),source:x.source}))},profiles:VERIFIED_PROFILE_REGISTRY.map(p=>({id:p.id,unitId:p.unitId,programs:p.programs,workTypes:p.workTypes,status:p.status,variant:p.variant||null,verifiedAt:p.verifiedAt||null,ruleAuthority:p.ruleAuthority||null,sources:(p.sources||[]).map(x=>x.url)})),departments:LEGAL_DEPARTMENT_REGISTRY.map(d=>({id:d.id,name:d.name,programs:d.programs,workTypes:d.workTypes,status:d.status,ruleAuthority:d.ruleAuthority,sources:(d.sources||[]).map(x=>x.url)}))}}
function runRegistryDiagnostics(){const rows=[],add=(level,title,detail)=>rows.push({level,title,detail});const profileIds=VERIFIED_PROFILE_REGISTRY.map(x=>x.id),departmentIds=LEGAL_DEPARTMENT_REGISTRY.map(x=>x.id),unitMap=new Map(allUnits().map(x=>[x.id,x]));for(const [label,ids]of [['Profil',profileIds],['Katedarski profil',departmentIds]]){const dup=[...new Set(ids.filter((x,i)=>ids.indexOf(x)!==i))];add(dup.length?'fail':'pass',`${label}: jedinstveni ID-jevi`,dup.length?`Duplikati: ${dup.join(', ')}`:`${ids.length} jedinstvenih zapisa`)}for(const p of VERIFIED_PROFILE_REGISTRY){const unit=unitMap.get(p.unitId);if(!unit){add('fail',p.id,`Nepostojeći unitId: ${p.unitId}`);continue}const missingPrograms=(p.programs||[]).filter(x=>!unit.programs.includes(x));if(missingPrograms.length)add('fail',p.id,`Program nije u katalogu: ${missingPrograms.join(', ')}`);const badTypes=(p.workTypes||[]).filter(x=>!VALID_WORK_TYPES.has(x));if(badTypes.length)add('fail',p.id,`Nepoznata vrsta rada: ${badTypes.join(', ')}`);if(!p.rules||typeof p.rules!=='object')add('fail',p.id,'Nedostaje rules objekt');const badSources=(p.sources||[]).filter(x=>!/^https:\/\//.test(x.url||''));if(badSources.length)add('warn',p.id,`${badSources.length} izvora nije HTTPS`);const citation=p.rules?.recommendedCitation;if(citation&&!VALID_CITATION_IDS.has(citation))add('fail',p.id,`Nepoznat citatni profil: ${citation}`)}const pravo=unitMap.get('pravo');for(const d of LEGAL_DEPARTMENT_REGISTRY){const missing=(d.programs||[]).filter(x=>!pravo?.programs.includes(x));if(missing.length)add('fail',d.id,`Program nije u katalogu Pravnog fakulteta: ${missing.join(', ')}`);const bad=(d.workTypes||[]).filter(x=>!VALID_WORK_TYPES.has(x));if(bad.length)add('fail',d.id,`Nepoznata vrsta rada: ${bad.join(', ')}`);if(!(d.sources||[]).length)add('warn',d.id,'Nema službenog izvora')}const coveredFpzg=['fpzg-politologija-zavrsni','fpzg-novinarstvo-zavrsni-tekst','fpzg-novinarstvo-zavrsni-av','fpzg-politologija-diplomski','fpzg-nacionalna-sigurnost-diplomski','fpzg-novinarstvo-diplomski'];const missingFpzg=coveredFpzg.filter(id=>!VERIFIED_PROFILE_REGISTRY.some(p=>p.id===id));add(missingFpzg.length?'fail':'pass','FPZG v2.2.2 predajni profili',missingFpzg.length?`Nedostaju: ${missingFpzg.join(', ')}`:'6/6 odvojenih profila povezano s godišnjim kalendarom 2025./2026.');const matrixRows=coverageSnapshot().rows,matrixIds=matrixRows.map(x=>x.id),matrixDup=[...new Set(matrixIds.filter((x,i)=>matrixIds.indexOf(x)!==i))];add(matrixDup.length?'fail':'pass','Institucionalna matrica: jedinstveni ID-jevi',matrixDup.length?`Duplikati: ${matrixDup.join(', ')}`:`${matrixIds.length} jedinstvenih programa`);for(const unitId of ['fpzg','pravo']){const unit=unitMap.get(unitId),matrixPrograms=matrixRows.filter(x=>x.unitId===unitId).map(x=>x.name),catalogPrograms=(unit?.programs||[]).filter(x=>!/^Opći/.test(x));const absent=matrixPrograms.filter(x=>!catalogPrograms.includes(x)),unmapped=catalogPrograms.filter(x=>!matrixPrograms.includes(x));add(absent.length||unmapped.length?'fail':'pass',`${unitId.toUpperCase()}: katalog ↔ matrica`,absent.length||unmapped.length?`Nema u katalogu: ${absent.join(', ')||'—'}; nema u matrici: ${unmapped.join(', ')||'—'}`:`${matrixPrograms.length} programa u potpunosti mapirano`)}const matrixGaps=matrixRows.filter(x=>['missing','partial','published'].includes(x.evaluation.status));add(matrixGaps.length?'warn':'pass','Preostali razvojni jaz',matrixGaps.length?`${matrixGaps.length} internih programa još nije na statusu potpune spremnosti.`:'Svi interni programi imaju potpuni profil.');const externalRows=matrixRows.filter(x=>x.evaluation.status==='external');add('pass','Partnerski i združeni programi',`${externalRows.length} programa odvojeno označeno kao vanjsko upravljanje pravilima.`);const ps=productionStatus();add(ps.active?'pass':'warn','Produkcijska predaja',ps.active?`Aktivna: ${ps.endpoint}`:'Nije aktivirana; koristi se lokalni fallback.');add(ps.links===PACKAGES.length?'pass':'warn','Payment linkovi',`${ps.links}/${PACKAGES.length} paketa ima konfiguriran checkout.`);add(productionConfig.contactEmail?'pass':'warn','Kontakt privatnosti',productionConfig.contactEmail||'Kontakt e-mail nije konfiguriran.');if(productionConfig.analyticsEndpoint)add(safeStorageGet(STORAGE_KEYS.analyticsConsent)?'pass':'warn','Klijentska analitika','Endpoint postoji; privola se prikuplja u sučelju.');else add('pass','Klijentska analitika','Nije uključena; nema klijentskog praćenja.');if(!rows.some(x=>x.level==='fail'))add('pass','Usmjeravanje profila','Nisu pronađene blokirajuće pogreške u registrima.');return rows}
function openQa(){const rows=runRegistryDiagnostics(),pass=rows.filter(x=>x.level==='pass').length,warn=rows.filter(x=>x.level==='warn').length,fail=rows.filter(x=>x.level==='fail').length,cov=coverageSnapshot().counts;$('#qaResults').innerHTML=`<div class="qa-summary"><div class="qa-stat"><span>PROGRAMI</span><b>${cov.total}</b></div><div class="qa-stat"><span>SPREMNO</span><b>${cov.ready}</b></div><div class="qa-stat"><span>PROFILI</span><b>${VERIFIED_PROFILE_REGISTRY.length}</b></div><div class="qa-stat"><span>UPOZORENJA</span><b>${warn}</b></div><div class="qa-stat"><span>POGREŠKE</span><b>${fail}</b></div></div><div class="qa-list">${rows.map(x=>`<div class="qa-row ${x.level}"><span>${x.level==='pass'?'<i data-lucide="check-circle"></i>':x.level==='fail'?'<i data-lucide="alert-circle"></i>':'<i data-lucide="alert-triangle"></i>'}</span><div><strong>${escapeHtml(x.title)}</strong><p>${escapeHtml(x.detail)}</p></div></div>`).join('')}</div><p class="profile-note"><strong>Rezultat:</strong> ${pass} prolaznih provjera, ${warn} upozorenja i ${fail} blokirajućih pogrešaka. QA konzola provjerava strukturu registra, ne sadržaj službenih dokumenata.</p>`;window.__lektaIcons?.();$('#qaModal').classList.remove('hidden');trapModal($('#qaModal'))}
function closeQa(){$('#qaModal')?.classList.add('hidden');releaseModal($('#qaModal'))}
function downloadProfileManifest(){downloadBlob(JSON.stringify(profileManifest(),null,2),'application/json',`Lekta-profile-manifest-v${APP_VERSION}.json`)}
function reportEndpointConfigured(){return!!String(productionConfig?.reportEndpoint||'').trim()}
function eurLabel(n){return`${Number(n).toFixed(2).replace('.',',')} EUR`}
const SESSION_KEY='lekta.session';
const authStore={load:()=>safeStorageGet(SESSION_KEY,null),save:s=>safeStorageSet(SESSION_KEY,s)};
function authConfig(){return{supabaseUrl:String(productionConfig?.supabaseUrl||'').trim(),anonKey:String(productionConfig?.supabaseAnonKey||'').trim()}}
function authConfigured(){const c=authConfig();return!!(c.supabaseUrl&&c.anonKey)}
// Valjan pristupni token: iz Supabase sesije ako je auth konfiguriran (null -> pozivatelj otvara prijavu),
// inace legacy reportToken (nekonfigurirano okruzenje se ponasa kao dosad).
async function resolveAccessToken(){if(authConfigured()){try{return await getValidAccessToken(authConfig(),authStore)}catch(e){return null}}return String(productionConfig?.reportToken||'')}
let _authEmail='',_authStep='email',_pendingAuthAction=null;
function setAuthStatus(type,msg){const st=$('#authStatus');if(!st)return;if(!msg){st.className='order-status hidden';st.textContent='';return}st.className=`order-status ${type}`;st.textContent=msg}
function resetAuthModal(){_authEmail='';_authStep='email';const em=$('#authEmail'),cc=$('#authCode');if(em){em.value='';em.disabled=false}if(cc)cc.value='';$('#authCodeField')?.classList.add('hidden');$('#authChangeEmail')?.classList.add('hidden');const sub=$('#authSubmit');if(sub){sub.textContent='Pošalji kod';sub.disabled=false}setAuthStatus('','')}
function openAuth(afterSignIn){_pendingAuthAction=afterSignIn||null;resetAuthModal();$('#authModal')?.classList.remove('hidden');trapModal($('#authModal'));setTimeout(()=>$('#authEmail')?.focus(),40)}
function closeAuth(){$('#authModal')?.classList.add('hidden');releaseModal($('#authModal'))}
async function authSubmit(){const sub=$('#authSubmit');if(!sub)return;if(sub.disabled)return;if(_authStep==='email'){const email=($('#authEmail')?.value||'').trim();sub.disabled=true;setAuthStatus('pending','Šaljem kod…');const out=await requestEmailOtp(authConfig(),email);sub.disabled=false;if(out.ok){_authEmail=email;_authStep='code';const em=$('#authEmail');if(em)em.disabled=true;$('#authCodeField')?.classList.remove('hidden');$('#authChangeEmail')?.classList.remove('hidden');sub.textContent='Potvrdi kod';setAuthStatus('success',`Kod je poslan na ${email}. Provjeri i mapu neželjene pošte.`);setTimeout(()=>$('#authCode')?.focus(),40)}else{setAuthStatus('error',out.message||'Slanje koda nije uspjelo.')}}else{const code=($('#authCode')?.value||'').trim();sub.disabled=true;setAuthStatus('pending','Provjeravam kod…');const out=await verifyEmailOtp(authConfig(),_authEmail,code);sub.disabled=false;if(out.ok){authStore.save(out.session);closeAuth();toast('Prijava uspješna.');trackEvent('auth_signed_in',{});const a=_pendingAuthAction;_pendingAuthAction=null;if(a)a()}else{setAuthStatus('error',out.message||'Kod nije točan.')}}}
function authChangeEmail(){_authStep='email';const em=$('#authEmail');if(em)em.disabled=false;const cc=$('#authCode');if(cc)cc.value='';$('#authCodeField')?.classList.add('hidden');$('#authChangeEmail')?.classList.add('hidden');const sub=$('#authSubmit');if(sub)sub.textContent='Pošalji kod';setAuthStatus('','');em?.focus()}
function checkoutConfigured(){return!!String(productionConfig?.checkoutEndpoint||'').trim()}
function resetUnlockButton(){const ub=$('#unlockReport');if(!ub)return;ub.textContent='Otključaj puni izvještaj';ub.onclick=handleUnlockReport;ub.disabled=false;ub.classList.toggle('hidden',!reportEndpointConfigured())}
// Klijentski checkout: salje samo productId (kriterij 14.1). Bez Supabase JWT-a server
// vraca 401 pa se prikaze uputa za prijavu. Puni tok radi tek kad je backend spojen.
async function startReportCheckout(workType){const productId=slotProductForWorkType(workType);if(!productId){toast('Za ovu vrstu rada checkout nije dostupan.');return}const token=await resolveAccessToken();if(authConfigured()&&!token){openAuth(()=>startReportCheckout(workType));return}const ub=$('#unlockReport');if(ub)ub.disabled=true;toast('Otvaram sigurno plaćanje…');try{const out=await createCheckout({endpoint:String(productionConfig.checkoutEndpoint).trim()},token,productId);if(out.kind==='ok'){trackEvent('checkout_started',{product:productId});location.href=out.checkoutUrl;return}if(out.kind==='unauthorized')toast('Za kupnju paketa potrebna je prijava.');else if(out.kind==='forbidden')toast('Ovaj paket trenutačno nije dostupan.');else if(out.kind==='not_found')toast('Paket nije pronađen u katalogu.');else toast('Plaćanje trenutačno nije dostupno.')}catch(e){toast('Greška pri otvaranju plaćanja.')}finally{if(ub)ub.disabled=false}}
let _retailCatalog=null;
// Cijene iz products tablice (kriterij 14.2, "cijena bez deploya"): dohvat je lijeni i
// kesiran; paywall preferira zivu cijenu, a na bilo koji neuspjeh pada na WORK_TYPE_TIERS.
async function ensureRetailCatalog(force){if(_retailCatalog&&!force)return _retailCatalog;const supabaseUrl=String(productionConfig?.supabaseUrl||'').trim(),anonKey=String(productionConfig?.supabaseAnonKey||'').trim();if(!supabaseUrl||!anonKey)return null;try{_retailCatalog=await fetchRetailCatalog({supabaseUrl,anonKey})}catch(e){_retailCatalog=null}return _retailCatalog}
function livePriceEur(workType){if(!_retailCatalog)return null;const p=_retailCatalog.find(x=>x.kind==='slot'&&x.audience==='retail'&&x.active&&x.workType===workType);return p&&isFinite(p.priceEur)?p.priceEur:null}
function showPaywall(workType){const tier=tierFor(workType),price=tier?(livePriceEur(tier.workType)??tier.priceEur):0,label=tier?`${tier.label} (${eurLabel(price)})`:workType,ub=$('#unlockReport');if(checkoutConfigured()&&tier&&ub){ub.classList.remove('hidden');ub.disabled=false;ub.textContent=`Kupi paket: ${tier.label} · ${eurLabel(price)} →`;ub.onclick=()=>startReportCheckout(tier.workType);toast(`Za puni izvještaj potreban je paket: ${label}.`)}else{toast(`Za puni izvještaj potreban je paket: ${label}.`);document.querySelector('#pricing')?.scrollIntoView({behavior:'smooth'})}}
async function handleUnlockReport(){if(!currentResult)return;if(!reportEndpointConfigured()){toast('Puni izvještaj nije konfiguriran u ovom okruženju.');return;}const ub=$('#unlockReport');if(ub)ub.disabled=true;const token=await resolveAccessToken();if(authConfigured()&&!token){if(ub)ub.disabled=false;openAuth(()=>handleUnlockReport());return}try{const cfg={endpoint:String(productionConfig.reportEndpoint).trim()},workType=currentResult.settings?.workType||$('#workType')?.value||'final';const out=await unlockReportRequest(currentResult,workType,cfg,token);if(out.kind==='ok'){currentResult.fullReport=out.report;renderFullReportBanner(currentResult);toast('Puni izvještaj je otključan.');trackEvent('full_report_unlocked',{profileId:currentResult.details?.profileDefinitionId||''})}else if(out.kind==='paywall'){showPaywall(out.workType)}else if(out.kind==='unauthorized'){toast('Prijava je potrebna za puni izvještaj.')}else if(out.kind==='rate_limited'){toast('Previše zahtjeva u kratko vrijeme. Pokušaj kasnije.')}else{toast('Puni izvještaj trenutačno nije dostupan.')}}catch(e){toast('Greška pri otključavanju izvještaja.')}finally{if(ub)ub.disabled=false}}
function syncUnlockButton(){const ub=$('#unlockReport');if(ub)ub.classList.toggle('hidden',!reportEndpointConfigured())}
// Prikaz punog izvjestaja: banner se pojavi tek kad server vrati fullReport (coverageTier +
// traceToken). Do tada je skriven; teaser rezultat ostaje potpuno lokalan i besplatan.
function renderFullReportBanner(r){const el=$('#fullReportBanner');if(!el)return;const fr=r&&r.fullReport;if(!fr){el.classList.add('hidden');el.innerHTML='';return}const tier=Number(fr.coverageTier)||0,labels=['Osnovna pokrivenost','Proširena pokrivenost','Verificirana pokrivenost (garancija)','Potpuna pokrivenost (garancija)'],tierLabel=labels[tier]||`Razina ${tier}`,token=fr.traceToken?`<span class="frb-token">trag: ${escapeHtml(String(fr.traceToken))}</span>`:'';const checks=Array.isArray(fr.checks)?fr.checks:[],cnt=k=>checks.filter(c=>c&&c.confidence===k).length,scored=typeof fr.scoredCount==='number'?fr.scoredCount:checks.length-cnt('informational'),unver=typeof fr.unverifiedCount==='number'?fr.unverifiedCount:cnt('informational'),high=cnt('high'),med=cnt('medium'),low=cnt('low'),conf=`<span class="frb-conf">Bodovano: ${scored}${high||med||low?` (visoka ${high}, srednja ${med}, niska ${low})`:''}</span><span class="frb-conf frb-unver">Nepotvrđeno: ${unver}</span>`;el.classList.remove('hidden');el.innerHTML=`<span class="frb-title"><i data-lucide="badge-check"></i> Puni izvještaj otključan</span><span class="frb-tier">${escapeHtml(tierLabel)}</span>${conf}${token}<p class="frb-note">Bodovana pravila nose oznaku pouzdanosti prema statusu profila; nepotvrđene stavke prikazuju se informativno i ne ulaze u ocjenu. Puni izvještaj je serverski potvrđen i bez vodenog žiga.</p>`;window.__lektaIcons?.()}
function renderLegalCitationSummary(r){const el=$('#legalCitationSummary'),engine=r.details?.legalCitationEngine;if(!engine){el.classList.add('hidden');el.innerHTML='';return}el.classList.remove('hidden');const labels=LEGAL_SOURCE_LABELS;const chips=Object.entries(engine.typeCounts||{}).filter(([,n])=>n>0).sort((a,b)=>b[1]-a[1]).map(([k,n])=>`<span class="legal-type-chip"><strong>${escapeHtml(labels[k]||k)}</strong> · ${n}</span>`).join('');const problems=(engine.problems||[]).slice(0,6).map(p=>`<div class="legal-problem"><strong>Bilješka ${escapeHtml(p.note)}</strong>${escapeHtml(p.message)}</div>`).join('');const coverage=Math.round((engine.coverage||0)*100);el.innerHTML=`<section class="legal-engine"><div class="legal-engine-head"><div><h3>Legal Citation Engine</h3><p>Heuristički povezuje prva i ponovljena navođenja, propise, sudsku praksu i bibliografiju. Rezultat treba potvrditi u kontekstu rada.</p></div><span class="legal-engine-badge">${coverage}% klasificirano</span></div><div class="legal-engine-grid"><div class="legal-engine-card"><span>Fusnote</span><b>${fmt(engine.summary?.footnotes||0)}</b></div><div class="legal-engine-card"><span>op. cit. / Ibid. / id.</span><b>${fmt((engine.summary?.opCit||0)+(engine.summary?.ibid||0)+(engine.summary?.id||0))}</b></div><div class="legal-engine-card"><span>Pravni akti</span><b>${fmt(engine.summary?.legalActs||0)}</b></div><div class="legal-engine-card"><span>Sudske odluke</span><b>${fmt(engine.summary?.cases||0)}</b></div></div><div class="legal-type-list">${chips||'<span class="legal-type-chip">Nema klasificiranih izvora</span>'}</div>${problems?`<div class="legal-problem-list">${problems}</div>`:''}<div class="legal-engine-note">Povezivanje je konzervativno: nepoznat ili složen navod označava se za ručni pregled umjesto da se automatski proglasi pogrešnim.</div></section>`}
function renderDeadlineCalendar(bp){if(!bp.deadlineCalendar)return'';const c=bp.deadlineCalendar,entries=c.entries||[],milestones=(c.milestones||[]).map(m=>`<span class="deadline-milestone"><strong>${escapeHtml(m.label)}:</strong> ${escapeHtml(hrDate(m.date))}</span>`).join(''),cards=entries.map(x=>{const state=x.state||deadlineState(x),selected=x.id===c.selectedId,cutoff=x.cutoff?`<p><strong>Krajnji rok:</strong> ${escapeHtml(hrDate(x.cutoff,true))}</p>`:'<p><strong>Prijava:</strong> najmanje 3 radna dana prije obrane</p>',mentor=x.mentorDraftDeadline?`<p><strong>Završna verzija mentoru:</strong> ${escapeHtml(hrDate(x.mentorDraftDeadline))}</p>`:'';return`<article class="deadline-card ${selected?'selected':''} ${state.key==='closed'?'closed':''}"><h4>${escapeHtml(x.label)}</h4>${cutoff}${mentor}<p><strong>Obrane:</strong> ${escapeHtml(dateRange(x.defenseStart||x.start,x.defenseEnd||x.end))}</p><span class="deadline-status ${escapeHtml(state.key)}">${escapeHtml(state.label)}${selected?' · odabrano':''}</span></article>`}).join('');const cohort=c.type==='final'?` · ${c.cohort==='carried'?'prenesen iz 2024./2025.':'upisan u 2025./2026.'}`:'';return`<section class="deadline-board"><div class="deadline-board-head"><div><h3>Godišnji rokovi · ${escapeHtml(bp.profileLabel||'FPZG')}</h3><p>Službeni raspored obrana i krajnjih rokova za odabrani profil${escapeHtml(cohort)}.</p></div><span class="deadline-year">${escapeHtml(c.academicYear)}</span></div>${milestones?`<div class="deadline-milestones">${milestones}</div>`:''}<div class="deadline-grid">${cards}</div><div class="deadline-foot"><strong>Napomena:</strong> status se računa prema datumu na uređaju. Ručna potvrda ostaje potrebna jer aplikacija ne može znati je li prijava već predana.</div></section>`}
function renderSubmissionChecklist(r){
 const a=renderSubmissionGate(r),bp=a.blueprint,manual=a.manual,deadlineHtml=renderDeadlineCalendar(bp);renderPdfPreflight();const count=bp.items.length+a.files.blockers.length+a.files.warnings.length;$('#submissionTabCount').textContent=count?`(${count})`:'';
 const blockers=[...a.files.blockers.map(x=>`<div class="crossfile-warning"><strong>Blokira predaju:</strong> ${escapeHtml(x)}</div>`),...a.files.warnings.map(x=>`<div class="crossfile-warning"><strong>Treba potvrditi:</strong> ${escapeHtml(x)}</div>`)].join('');
 const groups=[...new Set(bp.items.map(x=>x.section))].map(section=>`<div class="phase-block"><div class="phase-title">${escapeHtml(section)}</div><div class="phase-list">${bp.items.filter(x=>x.section===section).map(x=>`<label class="phase-item"><input type="checkbox" data-submission-check="${escapeHtml(x.id)}" ${manual[x.id]?'checked':''}><div><strong>${escapeHtml(x.label)}</strong><p>${escapeHtml(x.description||'')}</p></div><span class="phase-tag ${x.blocking?'blocking':''}">${x.blocking?'obvezno':'informativno'}</span></label>`).join('')}</div></div>`).join('');
 const meta=currentMetadataAudit?`<div class="${currentMetadataAudit.compliant?'crossfile-ok':'crossfile-warning'}"><strong>Zasebni Word:</strong> ${currentMetadataAudit.valid?(currentMetadataAudit.complete?`Prepoznati su dvojezični elementi. Ključne riječi HR/EN: ${currentMetadataAudit.keywordCounts?.hr??'—'}/${currentMetadataAudit.keywordCounts?.en??'—'}; rečenice sažetka HR/EN: ${currentMetadataAudit.summarySentences?.hr??'—'}/${currentMetadataAudit.summarySentences?.en??'—'}.`:'Nisu prepoznati svi očekivani dvojezični elementi.'):'Datoteku nije moguće pročitati.'}</div>`:'';
 const sources=(bp.sources||[]).map(x=>`<div class="source-line">Službeni izvor: <a href="${escapeHtml(x.url)}" target="_blank" rel="noopener">${escapeHtml(x.title)}</a></div>`).join('');$('#submissionChecklist').innerHTML=`<div class="submission-intro"><strong>Submission Gate nije službena potvrda fakulteta.</strong> Automatizirano provjerava dostupne elemente datoteka, a administrativne obveze potvrđuješ ručno prema aktualnom službenom postupku. Pravila su zadnji put provjerena ${escapeHtml(bp.sourceDate)}.</div>${deadlineHtml}${blockers}${meta}${selectedAvFile?`<div class="crossfile-ok"><strong>Audiovizualni prilog:</strong> ${escapeHtml(selectedAvFile.name)} · ${(selectedAvFile.size/1024/1024).toFixed(2)} MB · evidentirano samo lokalno.</div>`:''}${groups||'<div class="empty">Za način „Samo dokument” nema administrativne checkliste.</div>'}${sources?`<div class="source-stack">${sources}</div>`:''}<div class="submission-tools"><button class="btn btn-secondary btn-sm" type="button" data-download-submission>Preuzmi paketni izvještaj</button></div>`;
}

function renderCheckTable(id,items){$('#'+id).innerHTML=`<div style="overflow:auto"><table class="check-table"><thead><tr><th>Provjera</th><th>Status</th><th>Rezultat</th><th>Bodovi</th></tr></thead><tbody>${items.map(c=>`<tr><td><strong>${escapeHtml(c.title)}</strong></td><td><span class="status ${c.max===0?'pass':c.status}">${c.max===0?'<i data-lucide="info"></i> Informativno':c.status==='pass'?'<i data-lucide="check-circle"></i> U redu':c.status==='fail'?'<i data-lucide="alert-circle"></i> Važno':'<i data-lucide="alert-triangle"></i> Provjeri'}</span></td><td>${escapeHtml(c.detail)}</td><td>${c.max===0?'—':Math.round(c.earned*10)/10+'/'+c.max}</td></tr>`).join('')}</tbody></table></div>`}
function renderIssues(filter='all'){if(!currentResult)return;const arr=currentResult.issues.filter(i=>filter==='all'||i.severity===filter);$('#issueCountLabel').textContent=`Prikazano ${arr.length} od ${currentResult.issues.length}`;$('#issuesList').innerHTML=arr.length?arr.map(i=>`<article class="issue ${i.severity}"><div class="issue-icon">${i.severity==='error'?'<i data-lucide="alert-circle"></i>':i.severity==='warning'?'<i data-lucide="alert-triangle"></i>':'<i data-lucide="info"></i>'}</div><div><h4>${escapeHtml(i.title)}</h4><p>${escapeHtml(i.detail)}</p></div><span class="where">${escapeHtml(i.where||i.category)}</span></article>`).join(''):'<div class="empty"><i data-lucide="check-circle"></i><p>Nema problema u ovoj kategoriji. Sve stavke ovog filtra su uredne.</p></div>';window.__lektaIcons?.()}
// Otkrij drugi red tabova (iza "Više detalja") bez zatvaranja; koristi ga i klik na kategorijsku karticu.
function revealDetails(){const d=$('#tabDetails');if(d&&d.hasAttribute('hidden')){d.removeAttribute('hidden');$('#detailsToggle')?.classList.add('open');$('#detailsToggle')?.setAttribute('aria-expanded','true')}}
function openTab(id){$$('.tab').forEach(b=>{const on=b.dataset.tab===id;b.classList.toggle('active',on);b.setAttribute('aria-selected',on?'true':'false');b.setAttribute('tabindex',on?'0':'-1')});$$('.tab-panel').forEach(p=>p.classList.toggle('active',p.id===`tab-${id}`))}
function resetAnalyzer(){currentResult=null;resetUnlockButton();$('#resultView').classList.add('hidden');$('#progressView').classList.add('hidden');$('#wizardView').classList.remove('hidden');setFile(null);setAuxFile('pdf',null);setAuxFile('metadata',null);setAuxFile('av',null);progress(0,'Pripremam analizu');document.querySelector('#analyzer').scrollIntoView({behavior:'smooth'})}
function downloadResult(){if(!currentResult)return;const exportResult=structuredClone(currentResult);exportResult.submission=submissionAssessment(currentResult);exportResult.details.pdfPreflight=currentPdfAudit;exportResult.details.metadataDocument=currentMetadataAudit;downloadBlob(JSON.stringify(exportResult,null,2),'application/json',`Lekta-izvjestaj-${currentResult.file.name.replace(/\.docx$/i,'')}.json`);trackEvent('report_downloaded',{source:'json',profileId:currentResult.details?.profileDefinitionId||''})}
function openOrder(id='format'){currentPackage=id;$$('input[name="package"]').forEach(r=>r.checked=r.value===id);clearOrderStatus();$('#orderConsent').checked=false;renderProductionState();updateOrderFileMeta();$('#orderModal').classList.remove('hidden');trapModal($('#orderModal'));trackEvent('order_opened',{package:id,provider:productionConfig.paymentProvider});setTimeout(()=>$('#orderName').focus(),50)}function closeOrder(){$('#orderModal').classList.add('hidden');releaseModal($('#orderModal'))}
async function submitOrder(){const name=$('#orderName').value.trim(),email=$('#orderEmail').value.trim(),pkg=$('input[name="package"]:checked')?.value,file=selectedOrderFile(),consent=$('#orderConsent').checked;if(!name||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){toast('Upiši ime i valjanu e-mail adresu.');return}if(!consent){toast('Za slanje narudžbe potrebno je prihvatiti uvjete i obavijest o privatnosti.');return}if(file&&(!file.name.toLowerCase().endsWith('.docx')||file.size>productionConfig.uploadMaxBytes)){setOrderStatus('error',`Dokument mora biti .docx i ne smije biti veći od ${Math.round(productionConfig.uploadMaxBytes/1024/1024)} MB. Narudžbu možeš poslati bez datoteke i naknadno dogovoriti drugi siguran kanal.`);return}const orderId=makeOrderId(),profile=currentProfile().p,order={orderId,createdAt:new Date().toISOString(),customer:{name,email},package:PACKAGES.find(p=>p.id===pkg),deadline:$('#orderDeadline').value||null,notes:$('#orderNotes').value.trim(),marketingConsent:$('#orderMarketing').checked,termsVersion:TERMS_VERSION,document:file?{name:file.name,size:file.size,type:file.type}:null,analysis:currentResult?{file:currentResult.file.name,score:currentResult.score,profile:currentResult.profile,profileStatus:currentResult.profileStatus,fingerprint:currentResult.profileFingerprint||null,selection:currentResult.selection}:null,requestedProfile:profile.selection,status:'PENDING'};trackEvent('order_submit_attempt',{package:pkg,profileId:profile.definitionId||profile.id,workType:profile.selection.workType,provider:productionConfig.paymentProvider});const button=$('#submitOrder');button.disabled=true;button.textContent='Šaljem…';setOrderStatus('pending','Pripremam sigurnu predaju narudžbe…');try{if(!productionStatus().active){order.status='LOCAL_DRAFT';downloadBlob(JSON.stringify(order,null,2),'application/json',`Lekta-narudzba-${orderId}.json`);saveOrderReceipt(order);setOrderStatus('success',`<strong>Testni zapis je izrađen.</strong> Narudžba ${escapeHtml(orderId)} nije poslana niti je dokument prenesen. Preuzeta je lokalna JSON datoteka za provjeru integracije.`);toast('Testna narudžba spremljena je lokalno.');return}const fd=new FormData();fd.append('form-name','lekta-orders');fd.append('order_id',orderId);fd.append('name',name);fd.append('email',email);fd.append('package',pkg);fd.append('deadline',order.deadline||'');fd.append('notes',order.notes);fd.append('profile',JSON.stringify(order.requestedProfile));fd.append('fingerprint',order.analysis?.fingerprint||'');fd.append('marketing_consent',String(order.marketingConsent));fd.append('terms_version',TERMS_VERSION);if(file)fd.append('document',file,file.name);const response=await fetch(productionConfig.orderEndpoint,{method:'POST',body:fd,headers:{Accept:'application/json, text/plain, */*'}});if(!response.ok)throw new Error(`HTTP ${response.status}`);order.status='RECEIVED';saveOrderReceipt(order);const payBase=productionConfig.paymentLinks?.[pkg]||'',payUrl=buildPaymentUrl(payBase,email,orderId,pkg),payment=payUrl?`<div class="payment-action"><a class="btn btn-primary btn-sm" id="paymentContinue" href="${escapeHtml(payUrl)}" target="_blank" rel="noopener">Nastavi na sigurno plaćanje →</a></div>`:`<div class="payment-action"><strong>Plaćanje još nije povezano.</strong> Potvrda i upute bit će poslane na navedeni e-mail.</div>`;setOrderStatus('success',`<strong>Narudžba ${escapeHtml(orderId)} je zaprimljena.</strong> ${file?'Dokument je uključen u sigurnu predaju.':'Narudžba je zaprimljena bez dokumenta.'}${payment}`);trackEvent('order_submitted',{package:pkg,profileId:profile.definitionId||profile.id,provider:productionConfig.paymentProvider});setTimeout(()=>{const a=$('#paymentContinue');if(a)a.onclick=()=>trackEvent('payment_redirect',{package:pkg,provider:productionConfig.paymentProvider})},0)}catch(err){order.status='FAILED';setOrderStatus('error',`Narudžbu nije bilo moguće poslati (${escapeHtml(err.message||'mrežna pogreška')}). Dokument nije označen kao zaprimljen. Pokušaj ponovno ili kontaktiraj ${escapeHtml(productionConfig.contactEmail||'podršku nakon konfiguracije kontakta')}.`)}finally{button.disabled=false;button.textContent='Pošalji narudžbu'}}
